function actesNotesAVoir(e){const t=[...String(e||"").matchAll(/\(\(([\s\S]+?)\)\)/g)].map(a=>a[1].replace(/\*/g,"").trim()),s=[];return t.forEach((a,n)=>{if(!(/^ibid\b/i.test(a)||/^(cf\.?|voir)\s/i.test(a)&&a.length<25)&&(/\b(1[5-9]|20)\d{2}\b/.test(a)||/\bp{1,2}\.\s*\d/.test(a)))try{const r=manquesRef(analyserRef(a),"notes");r.length&&s.push({n:n+1,texte:a,m:r})}catch{}}),{total:t.length,res:s}}
function enLigne(e){return esc(e).replace(/\(\(([\s\S]+?)\)\)/g,(t,s)=>`<span class="fn">${s.replace(/\*([^*]+)\*/g,"<em>$1</em>")}</span>`).replace(/\*([^*\n]+)\*/g,"<em>$1</em>")}
function texteVersHtml(e){return String(e||"").replace(/\r/g,"").split(`
`).map(t=>t.trim()).filter(Boolean).map(t=>/^###\s/.test(t)?`<h3>${enLigne(t.slice(4))}</h3>`:/^##\s/.test(t)?`<h2>${enLigne(t.slice(3))}</h2>`:/^>\s?/.test(t)?`<blockquote>${enLigne(t.replace(/^>\s?/,""))}</blockquote>`:`<p>${enLigne(t)}</p>`).join("")}
function biblioLigne(e,t){const s=e.split("|").map(d=>d.trim());if(s.length<3)return`<p class="bib">${enLigne(e)}</p>`;const[a,n,r,...i]=s,l=a?`<span class="sc">${esc(a)}</span>${n?" "+esc(prenomAbrege(n)):""}, `:"",o=t==="articles"?`« ${esc(r)} »`:`<em>${esc(r)}</em>`,c=i.filter(Boolean).map((d,u)=>t==="articles"&&u===0?`<em>${esc(d)}</em>`:/^\d+\s*-\s*\d+$/.test(d)&&u===i.length-1?"pp. "+esc(d.replace(/\s/g,"")):esc(d));return`<p class="bib">${l}${o}${c.length?", "+c.join(", "):""}.</p>`}
