(function () { let fait = false, n = -1, stable = 0;
  const fin = () => { if (fait) return; fait = true; window.apresMiseEnPage(); };
  try { window.PagedPolyfill && window.PagedPolyfill.on && window.PagedPolyfill.on('rendered', () => setTimeout(fin, 50)); } catch (e) {}
  const t = setInterval(() => { const k = document.querySelectorAll('.pagedjs_page').length; if (k && k === n) { if (++stable >= 3) { clearInterval(t); fin(); } } else { stable = 0; n = k; } }, 700);
})();
