        <label class="text-sm"><span class="block font-semibold mb-1">🗣 Langue du texte</span><select id="arLangue" class="field">${Object.entries(ART_LANGUES).map(([r,i])=>`<option value="${r}">${esc(i)}</option>`).join("")}</select></label>
