function skmCarte(e,t){const s=skmModeles().find(l=>l.id===e)||skmModeles()[0],a=`skm${++SKM_N}-`;if(s.genre==="ancien")return SK_CSS+skCouleurs()+skCarte(s.lg);const n=SKM_OPT.marge?(148-2*SKM_OPT.marge)/148:1,r=SKM_OPT.qr&&s.qr&&window.qrcode?`<div class="skm-qr" style="${s.qr}">${qrSvg(SITE_URL+"/#contact")}<span>PLAN D’ACCÈS</span></div>`:"",i=s.html(a,skmLangue(skmTextes()),t||{}).replace(/<\/div>$/,r+"</div>");return`<div class="skm sk-p${SKM_OPT.eco?" skm-eco":""}"${SKM_OPT.eco?' style="background:#fff"':""}>${n<1?`<div style="position:absolute;left:0;top:0;width:560px;height:794px;transform:scale(${n.toFixed(4)});transform-origin:280px 397px">${i}</div>`:i}</div>`}
